    const danmakuImportBtn = panel.querySelector('#danmaku-preset-import');
    const danmakuNameInput = panel.querySelector('#danmaku-preset-name');

    const renderDanmakuPresetsDropdown = (selectedVal = '') => {
      const userPresets = loadUserDanmakuPresets();
      let html = `<option value="" disabled ${!selectedVal ? 'selected' : ''}>-- Choose a Danmaku Preset --</option>`;

      html += `<optgroup label="Built-in Danmaku Presets">`;
      Object.keys(BUILTIN_DANMAKU_PRESETS).forEach(name => {
        const optVal = 'builtin:' + name;
        html += `<option value="${optVal}" ${selectedVal === optVal ? 'selected' : ''}>${name}</option>`;
      });
      html += `</optgroup>`;

      const userKeys = Object.keys(userPresets);
      if (userKeys.length > 0) {
        html += `<optgroup label="My Saved Danmaku Presets">`;
        userKeys.forEach(name => {
          const optVal = 'user:' + name;
          html += `<option value="${optVal}" ${selectedVal === optVal ? 'selected' : ''}>${name}</option>`;
        });
        html += `</optgroup>`;
      }

      danmakuPresetSelect.innerHTML = html;
      danmakuDeleteBtn.disabled = !selectedVal || !selectedVal.startsWith('user:');
    };

    const applyDanmakuTuningConfig = (newCfg, presetName) => {
      if (!window.danmakuTuning) window.danmakuTuning = {};
      Object.assign(window.danmakuTuning, newCfg);
      try {
        localStorage.setItem('f0ck_danmaku_tuning', JSON.stringify(window.danmakuTuning));
      } catch (e) {}

      danmakuSliders.forEach(s => {
        const input = panel.querySelector(`#input-danmaku-${s.key}`);
        const valEl = panel.querySelector(`#val-danmaku-${s.key}`);
        if (!input || !valEl) return;
        const val = window.danmakuTuning[s.key] !== undefined ? window.danmakuTuning[s.key] : (window.DEFAULT_DANMAKU_TUNING ? window.DEFAULT_DANMAKU_TUNING[s.key] : 0);
        input.value = val;
        if (s.type === 'color') {
          valEl.textContent = val;
        } else {
          const num = Number(val);
          const displayVal = Number.isInteger(num) ? num : parseFloat(num.toFixed(2));
          valEl.textContent = `${displayVal}${s.unit || ''}`;
        }
      });

      if (typeof Danmaku !== 'undefined' && typeof Danmaku.applyGlobalTuning === 'function') {
        Danmaku.applyGlobalTuning(window.danmakuTuning);
      } else if (window.danmakuInstance && typeof window.danmakuInstance._applyTuning === 'function') {
        window.danmakuInstance._applyTuning();
      }

      if (presetName && typeof window.flashMessage === 'function') {
        window.flashMessage(`Loaded danmaku preset: "${presetName}"`, 2200, 'info');
      }
    };

    renderDanmakuPresetsDropdown();

    danmakuPresetSelect.addEventListener('change', () => {
      const val = danmakuPresetSelect.value;
      if (!val) return;
      if (val.startsWith('builtin:')) {
        const name = val.replace('builtin:', '');
        if (BUILTIN_DANMAKU_PRESETS[name]) {
          applyDanmakuTuningConfig(BUILTIN_DANMAKU_PRESETS[name], name);
        }
        danmakuDeleteBtn.disabled = true;
      } else if (val.startsWith('user:')) {
        const name = val.replace('user:', '');
        const userPresets = loadUserDanmakuPresets();
        if (userPresets[name]) {
          applyDanmakuTuningConfig(userPresets[name], name);
        }
        danmakuDeleteBtn.disabled = false;
      }
    });

    const handleSaveDanmakuPreset = () => {
      let name = (danmakuNameInput.value || '').trim();
      if (!name) {
        name = prompt('Enter a name for this danmaku preset:');
        if (!name) return;
        name = name.trim();
      }
      if (!name) return;

      const userPresets = loadUserDanmakuPresets();
      userPresets[name] = Object.assign({}, window.danmakuTuning || {});
      saveUserDanmakuPresets(userPresets);

      danmakuNameInput.value = '';
      renderDanmakuPresetsDropdown('user:' + name);

      if (typeof window.flashMessage === 'function') {
        window.flashMessage(`Danmaku preset "${name}" saved!`, 2500, 'success');
      }
    };

    danmakuSaveBtn.addEventListener('click', handleSaveDanmakuPreset);
    danmakuNameInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleSaveDanmakuPreset();
      }
    });

    danmakuDeleteBtn.addEventListener('click', () => {
      const val = danmakuPresetSelect.value;
      if (!val || !val.startsWith('user:')) return;
      const name = val.replace('user:', '');
      if (!confirm(`Delete danmaku preset "${name}"?`)) return;

      const userPresets = loadUserDanmakuPresets();
      delete userPresets[name];
      saveUserDanmakuPresets(userPresets);

      renderDanmakuPresetsDropdown('');
      if (typeof window.flashMessage === 'function') {
        window.flashMessage(`Danmaku preset "${name}" deleted`, 2200, 'info');
      }
    });

    danmakuImportBtn.addEventListener('click', () => {
      const raw = prompt('Paste your danmaku preset JSON:');
      if (!raw) return;
      try {
        const parsed = JSON.parse(raw.trim());
        if (typeof parsed !== 'object' || parsed === null) {
          throw new Error('Not an object');
        }
        const defaultName = 'Danmaku Preset ' + new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        let name = prompt('Save danmaku preset as:', defaultName);
        name = name ? name.trim() : defaultName;

        const userPresets = loadUserDanmakuPresets();
        userPresets[name] = Object.assign({}, window.DEFAULT_DANMAKU_TUNING || {}, parsed);
        saveUserDanmakuPresets(userPresets);

        applyDanmakuTuningConfig(userPresets[name], name);
        renderDanmakuPresetsDropdown('user:' + name);

        if (typeof window.flashMessage === 'function') {
          window.flashMessage(`Imported and loaded "${name}"!`, 3000, 'success');
        }
      } catch (err) {
        alert('Invalid JSON! Please paste valid danmaku preset settings.');
      }
    });

