          img.alt = window.f0ckDomain || document.title;
          img.style.cssText = 'max-height:40px;vertical-align:middle;max-width:180px;width:auto;';
          img.onload = () => { if (window.syncNavbarHeight) window.syncNavbarHeight(); };
